from pathlib import Path
import json
R=Path(__file__).resolve().parent.parent
F=[]
def add(area,sev,title,steps,observed,expected,evidence):
 F.append(dict(id=f'L{len(F)+1:03d}',area=area,severity=sev,title=title,steps=steps,observed=observed,expected=expected,evidence=evidence.split()))
add('Pipes','P1','A pipeline destroys an existing PIPE1.$$$ file',r'Boot followup with multi-boot-fixture.img and followup-fixture.img. CD \T; TYPE PIPE1.$$$; TYPE ONE.TXT | SORT; DIR PIPE1.$$$; TYPE PIPE1.$$$.', 'The sentinel USER-OWNED-PIPE-FILE is readable before the pipe. The pipe prints ALPHA, then the sentinel file is gone. The stopped-image extraction also has no PIPE1.$$$.', 'Choose an unused temporary name and preserve existing files (tester expectation for temporary-file handling; original DOS Reference pp.132-135 describes pipes).', 'shots/followup-pipe-clobber.png evidence/followup-serial.log evidence/followup-filesystem.json evidence/followup.py')
add('Redirection','P1','Output to a full disk silently becomes an empty file',r'Boot re-full0 with multi-boot-fixture.img and full0-fixture.img. CD \T; DIR /W; ECHO TEST > FULL.OUT; DIR FULL.OUT; TYPE FULL.OUT.', 'DIR reports 0 bytes free. ECHO returns without an error; FULL.OUT exists with zero bytes instead of TEST plus CR/LF. The source files remain intact.', 'Report a disk-full write error; do not silently discard requested output (tester expectation; DOS Reference redirection pp.132-135).', 'shots/re-full0-redirection.png evidence/re-full0-serial.log evidence/storage-verification.json evidence/extracted/re-full0/T_FULL.OUT evidence/recheck.py')
add('Pipes','P1','A pipeline on a full disk silently loses its input',r'On the same full0 fixture, CD \T; TYPE ONE.TXT | SORT; ECHO PIPE-RETURNED.', 'The pipe prints nothing and no error. PIPE-RETURNED appears normally. ONE.TXT contains ALPHA plus CR/LF. Repeated after filling the last 512 bytes in re-full512.', 'Print ALPHA or report failure to create/write the pipe intermediate (tester expectation; DOS Reference pp.132-135).', 'shots/re-full0-pipe-empty.png evidence/re-full0-serial.log evidence/re-full512-serial.log evidence/recheck.py')
add('COPY diagnostics','P3','COPY reports Bad command for a disk-full write',r'On full0-fixture.img, CD \T; COPY LONG.TXT FULL.BIN; DIR FULL.BIN.', 'COPY prints Bad command or file name and leaves a zero-byte FULL.BIN. LONG.TXT exists and is 76800 bytes.', 'A disk-space/write failure diagnostic identifying why COPY failed; command syntax and source are valid (tester expectation).', 'shots/re-full0-copy-error.png evidence/re-full0-serial.log evidence/storage-verification.json')
add('Batch files','P2','A long batch file silently stops before its final command',r'Boot suite4 with multi-boot-fixture.img and suite-fixture.img; run \CASES\B063.BAT. It CALLs BIG.BAT, which contains BIG-BEGIN, 65 long REM lines, and BIG-END.', 'BIG-BEGIN and the caller\'s BIG-RETURNED print, but BIG-END never executes; no limit/error is reported.', 'Run the complete batch or explicitly reject it. InitechDOS Reference ch4-batch.tex:19-25 describes a batch as a sequence of commands, with no file-size restriction. Suspected cause (guess): os/milton/command.c:4212 BATCH_FILE_MAX=4096.', 'shots/suite4-B063-batch-long.png evidence/suite4-B063.txt evidence/cases/BIG.BAT evidence/cases/B063.BAT evidence/suite.py')
add('Batch SHIFT','P2','SHIFT loses arguments after the ninth',r'Run \CASES\B060.BAT, or TEN one two three four five six seven eight nine ten eleven on more-fixture.img.', 'The original ninth argument is nine. After SHIFT, %9 is empty; ten and eleven never become available.', 'Shift later arguments into %9 (DOS Reference printed p.151, PDF236). The Initech manual explicitly limits initial arguments to nine, but this is a DOS compatibility gap.', 'shots/suite4-B060-batch-args.png shots/advanced-misc-errorlevel-shift.png evidence/suite4-B060.txt evidence/advanced-misc-serial.log evidence/cases/ARGS.BAT evidence/more-fixtures/TEN.BAT evidence/manual-page-236.txt')
add('Batch documentation','P3','SHIFT changes %0 contrary to the shipped manual',r'Run \CASES\B060.BAT with its eleven arguments.', 'ZERO initially identifies the batch path; after SHIFT, ZERO=one.', 'The shipped Reference ch4-batch.tex:247 says "%0, the name of the batch file, is not changed." Actual shifting of %0 agrees with original DOS p.151; fix the manual contract rather than changing DOS-compatible behavior.', 'shots/suite4-B060-batch-args.png evidence/suite4-B060.txt evidence/cases/ARGS.BAT evidence/manual-page-236.txt')
add('Command lookup','P2','A path-qualified batch name requires the .BAT extension',r'Boot followup; CD \T; A:\T\BATCH2; A:\T\BATCH2.BAT; BATCH2.', 'The first form says Bad command or file name. Both controls print BATCH2-RAN.', 'Resolve .BAT for a qualified name as for a bare name. InitechDOS Reference ch4-batch.tex:32 says to type the name without its extension; original DOS batch invocation uses drive/path forms.', 'shots/followup-commands-env.png evidence/followup-serial.log evidence/special-fixtures/BATCH2.BAT')
add('COMMAND','P2','COMMAND without /C cannot open a nested prompt','Boot followup; type COMMAND. Then try COMMAND /C COMMAND /C ECHO NESTED.', 'Bare COMMAND says Invalid number of parameters. Nested /C works and prints NESTED.', 'Start a secondary command processor and allow EXIT back to the caller. InitechDOS Reference ch2-entries-b.tex:102-104 promises typing commands in a second copy; DOS Reference COMMAND pp.46-47.', 'shots/followup-commands-env.png evidence/followup-serial.log')
add('COMMAND error status','P2','COMMAND /C loses its child program exit status','Boot advanced-misc (geometry-boot-fixture.img, more-fixture.img); CD \\T; ERR0.COM; COMMAND /C ERR7.COM; IF ERRORLEVEL 7 ECHO CHILD-EXIT7; IF NOT ERRORLEVEL 7 ECHO CHILD-STATUS-LOST. Run ERR7.COM directly as a control.', 'The /C form prints CHILD-STATUS-LOST; the direct form prints DIRECT-EXIT7. ERR7.COM exits through INT 21h/AH=4Ch with AL=7.', 'Propagate the child status so ERRORLEVEL can test it (tester DOS command-processor expectation; Reference IF p.147 and Initech ch4-batch.tex:185-186).', 'shots/advanced-misc-errorlevel-shift.png evidence/advanced-misc-serial.log evidence/more-fixtures/ERR7.COM evidence/prepare_more.py')
add('CD','P2','CD drive: does not display that drive\'s current directory',r'Boot followup; CD \T; CD C:\CHOME; CD D:\DHOME; CD C:; CD D:; CD.', 'Both drive-only queries are silent; CD alone still prints A:\T. Drive-relative file access and switching drive show that per-drive directories were set.', 'Display C:\CHOME and D:\DHOME without switching drives (DOS Reference printed p.42/PDF127).', 'shots/followup-cd-tree-drive.png evidence/followup-serial.log evidence/suite4-B054.txt evidence/manual-page-127.txt')
add('ATTRIB','P2','ATTRIB cannot find a readable file on D:',r'Boot advanced-driveutils; CD \T; TYPE D:\DHOME\SAME.TXT; ATTRIB D:\DHOME\SAME.TXT; ATTRIB +R D:\DHOME\SAME.TXT.', 'TYPE prints D-DRIVE. Both ATTRIB forms print Invalid path (or file not found).', 'Read and set attributes on the specified mounted drive. InitechDOS Reference ch2-entries-a.tex:9-12 accepts a drive-qualified file.', 'shots/advanced-driveutils-failures.png evidence/advanced-driveutils-serial.log evidence/advanced.py')
add('CHKDSK','P2','CHKDSK reports a FAT error on valid C: and D: volumes','Boot advanced-driveutils using the geometry-corrected boot fixture; CHKDSK C:; CHKDSK D:. Compare ordinary DIR/TYPE/COPY operations on those volumes.', 'Both checks say Disk error reading (or writing) FAT. The same volumes support file reads and writes. CHKDSK on A: works.', 'Check the requested mounted FAT12 volume; do not report a disk error simply for its drive letter (DOS CHKDSK and InitechDOS Reference ch2-entries-a.tex, CHKDSK).', 'shots/advanced-driveutils-failures.png evidence/advanced-driveutils-serial.log evidence/suite4-B055.txt evidence/prepare.py evidence/prepare_more.py')
add('TREE','P2','TREE ignores an explicit other-drive operand',r'Boot suite4; CD \T; CD D:\DHOME; TREE D: /F. Also TREE D:\DHOME /F in followup.', 'TREE D: lists volume INITECH and A:\T contents. The absolute D: form says Invalid path despite the directory being readable with TYPE.', 'Walk the specified drive/path and label that volume (InitechDOS Reference ch2-entries-c.tex:125-140).', 'shots/suite4-B057-cross-drive-tools.png shots/followup-cd-tree-drive.png evidence/suite4-B057.txt evidence/followup-serial.log')
add('LABEL','P2','LABEL rejects a valid mounted D: volume','Boot suite4; VOL D:; LABEL D: NEWLABEL.', 'VOL displays EXTRA, but LABEL returns Invalid drive specification.', 'Apply the label to the requested valid drive (DOS LABEL; InitechDOS Reference ch2-entries-b.tex LABEL drive parameter).', 'shots/suite4-B057-cross-drive-tools.png evidence/suite4-B056.txt evidence/suite4-B057.txt')
add('FIND','P2','FIND ignores filename operands and waits for keyboard input',r'Boot suite2; run \CASES\B032.BAT, whose first command is FIND "Alpha" LINES.TXT. Wait 12 seconds; or run that command directly from A:\T.', 'No search results or file header appear; FIND waits for standard input. Ctrl-Z plus Enter returns. FIND "Alpha" < LINES.TXT works.', 'Open the named input file (DOS Reference pp.72-73/PDF157-158). Initech documentation only describes redirection; this is a compatibility gap.', 'shots/suite2-B032-BLOCKED.png evidence/suite2-serial.log evidence/interactive-serial.log evidence/cases/B032.BAT evidence/manual-page-157.txt')
add('FIND status','P2','FIND returns success when no line matches','Boot followup; CD \\T; FIND "absent" < ONE.TXT; IF ERRORLEVEL 1 ECHO RC1; IF NOT ERRORLEVEL 1 ECHO RC0.', 'No line matches, but RC0 is printed.', 'Return 1 when no matching line exists, 0 when a match exists (tester DOS FIND exit-status memory; distinguish from malformed-argument status).', 'shots/followup-find-quotes-exit.png evidence/followup-serial.log evidence/suite4-B064.txt')
add('FIND quoting','P2','FIND stops its search string at the first embedded quote','Boot followup; CD \\T; FIND "He said ""yes""" < QUOTES.TXT.', 'Both He said "yes" and He said no are printed, as if searching only for He said .', 'Match the embedded quoted word, returning only the first line (DOS Reference pp.72-73/PDF157-158, quotation-mark handling).', 'shots/followup-find-quotes-exit.png evidence/followup-serial.log evidence/special-fixtures/QUOTES.TXT evidence/manual-page-157.txt evidence/manual-page-158.txt')
add('FIND arguments','P3','FIND silently accepts an unknown switch','Boot followup; CD \\T; FIND /BAD "ALPHA" < ONE.TXT.', 'It prints ALPHA with no invalid-switch diagnostic.', 'Reject an unsupported switch with a useful error (tester expectation; valid switches listed on DOS p.72).', 'shots/followup-find-quotes-exit.png evidence/followup-serial.log evidence/manual-page-157.txt')
add('SORT','P2','SORT /+n ignores the requested starting column','Boot followup; CD \\T; SORT /+4 < SORTCOL.TXT. The input is 01 zebra then 02 apple.', 'The output remains 01 zebra then 02 apple.', 'Sort apple before zebra starting at column 4 (DOS Reference printed p.116/PDF201).', 'shots/followup-sort-column-cap.png evidence/followup-serial.log evidence/special-fixtures/SORTCOL.TXT evidence/manual-page-201.txt')
add('TIME','P2','TIME rejects hundredths of a second',r'Boot suite3; run \CASES\B039.BAT, or TIME 13:14:15.99.', 'Invalid time; previous time remains unchanged.', 'Accept the .hundredths field (DOS Reference p.120/PDF205). The narrower shipped Initech syntax does not promise it; this is DOS compatibility.', 'shots/suite3-B039-time-values.png evidence/suite3-B039.txt evidence/manual-page-205.txt')
add('VERIFY','P2','VERIFY is unavailable','Boot stock or suite3; VERIFY; VERIFY ON; VERIFY OFF.', 'All forms say Bad command or file name.', 'Provide the DOS write-verification switch and state query (DOS Reference p.125/PDF210). COPY /V is separately implemented.', 'shots/suite3-B042-builtin-gaps.png evidence/suite3-B042.txt evidence/manual-page-210.txt')
add('ECHO','P2','ECHO. cannot emit a blank line',r'Boot suite3; run \CASES\B036.BAT, or type ECHO. at the prompt.', 'Bad command or file name.', 'Output a blank line (tester DOS 3.x memory; no claim this shorthand is specified in the shipped manual).', 'shots/suite3-B036-echo.png evidence/suite3-B036.txt')
add('ECHO','P2','ECHO OFF at the prompt prints OFF and leaves echo on','Boot advanced-keyboard; ECHO OFF; ECHO; ECHO ON.', 'OFF is printed as ordinary text; the query still says ECHO is on. The batch form does change state.', 'Change echo state at the prompt too (tester DOS memory; DOS Reference p.143 documents ON/OFF). The Initech manual documents a separate, narrower prompt behavior.', 'shots/advanced-keyboard-interactive-expansion.png evidence/advanced-keyboard-serial.log evidence/manual-page-228.txt')
add('Environment expansion','P2','Percent-delimited variables are not expanded at the prompt','Boot advanced-keyboard; SET X=expanded; ECHO %X%.', 'The output is literally %X%.', 'Expand the environment reference to expanded (tester DOS command-line memory). Initech documentation only promises expansion in batch files, so this is compatibility, not a false manual-contract claim.', 'shots/advanced-keyboard-interactive-expansion.png evidence/advanced-keyboard-serial.log')
add('DIR','P2','DIR includes hidden and system files in normal listings',r'Boot suite2; run \CASES\B003.BAT. HIDDEN.TXT has +H and SYSTEM.TXT has +S, set by mattrib during fixture preparation.', 'DIR /W includes HIDDEN.TXT and SYSTEM.TXT; normal and .TXT listings do too.', 'Omit hidden/system files from ordinary DOS 3.3 DIR output (original DOS Reference DIR pp.57-58; tester attribute expectation).', 'shots/suite2-B003-dir-wide.png shots/suite2-B001-dir-paths.png evidence/suite2-B001.txt evidence/suite2-B003.txt evidence/preparation.json')
add('Redirection diagnostics','P3','Protected-file redirection reports Bad command',r'Boot suite2; CD \T; ECHO LOST > READONLY.TXT; ECHO LOST >> READONLY.TXT; TYPE READONLY.TXT.', 'Both attempts say Bad command or file name. The protected contents remain PROTECTED.', 'Report Access denied for a protected destination (tester diagnostic expectation; InitechDOS Reference ch2-entries-a.tex:227-228 uses that wording for COPY protection).', 'shots/suite2-B030-redir-readonly.png evidence/suite2-B030.txt evidence/extracted/suite2/T/READONLY.TXT')
add('FDISK display','P3','FDISK labels both mounted primary partitions C:','Boot advanced-fdisk with geometry-boot-fixture.img; FDISK; 4; Enter.', 'Both partition rows start C:, though the second volume is mounted and accessible as D:. The corrected CHS fixture rules out the earlier bad-cylinder display.', 'Show C: for the first and D: for the second mapped volume (tester consistency expectation; FDISK partition display).', 'shots/advanced-fdisk-partitions.png evidence/advanced-fdisk-serial.log evidence/prepare_more.py evidence/suite4-B056.txt')
add('Program error handling','P1','A malformed COM file halts the entire machine',r'Boot prog-garbage using program-fixture.img; CD \T; GARBAGE.COM. Fixture bytes are 0F 0B (invalid opcode). Try ECHO ALIVE afterwards.', 'PC LOAD LETTER / ERROR 06 appears; serial reports PANIC vec=06 and HALTED. No prompt returns.', 'Report the program failure and recover a usable shell (tester robustness expectation for this native hobby OS; not a promise that historical real-mode DOS isolated arbitrary programs). The panic wording itself is deliberate.', 'shots/prog-garbage-result.png evidence/prog-garbage-serial.log evidence/special-fixtures/T_GARBAGE.COM evidence/prepare_special.py')
add('Program loader','P1','An unsupported 16-bit MZ file halts without a screen diagnostic',r'Boot prog-mz16 using program-fixture.img; CD \T; DOS16.EXE. The crafted 32-byte MZ header and tiny 16-bit exit body are in prepare_special.py.', 'The screen stays on DOS16.EXE with no new prompt/message. Serial says foreign-mz: untagged 16-bit DOS .EXE and HALTED.', 'Refuse the unsupported format visibly and return to the shell; the brief explicitly requires a loud failure rather than a hang. Executing 16-bit programs is not demanded.', 'shots/prog-mz16-result.png evidence/prog-mz16-serial.log evidence/special-fixtures/T_DOS16.EXE evidence/prepare_special.py')
(R/'evidence/reconstructed-findings.json').write_text(json.dumps(F,indent=2))

def render(extra=None,tail=''):
 findings=F+(extra or [])
 out=['# InitechDOS audit - 2026-10-23','', 'Image build: `e67b8311092873fe16e6c6d62ad82f894bfb8d7d` (`images/COMMIT`). This report continues the interrupted audit in this directory. Findings L001-L030 form the initial reconstruction; later numbers add resumed checks and additional recovered cases. No original finding numbers were assigned in its narration.','', 'All tests use QEMU `-display none -cpu 486 -m 16 -qmp stdio`, with disposable disk copies. A: is the second IDE data disk; C: is the boot disk partition at byte 32256; D: is the added primary partition at byte 2097152. Commands below are typed with Enter unless another key is specified. Files, screenshots and logs are relative to this audit directory. Source and manual paths below are relative to `/home/tobias/Projects/initech-os/`.','', 'Original DOS reference: `/home/tobias/Projects/initech-manuals-ref/dos33/MS-DOS_3.3_Users_Guide_198707.pdf`; its reference-section printed pages are PDF page minus 85. Saved text extracts are `evidence/manual-page-N.txt`. Memory-based expectations are explicitly labeled.','', '## Findings','']
 for f in findings:
  out += [f"### {f['id']} - {f['title']}",'',f"Area: {f['area']}. Severity: {f['severity']}.",'',f"Steps: {f['steps']}",'',f"Observed: {f['observed']}",'',f"Expected and basis: {f['expected']}",'', 'Evidence: '+', '.join(f'[{p}]({p})' for p in f['evidence'])+'.','']
 out += [tail]
 (R/'REPORT.md').write_text('\n'.join(out),encoding='ascii')
 (R/'NITS.tsv').write_text('id\tarea\tseverity\tsummary\n'+''.join(f"{f['id']}\t{f['area']}\t{f['severity']}\t{f['title']}\n" for f in findings),encoding='ascii')
if __name__=='__main__':render(tail='Recovery draft: resumed tests and final coverage/status sections are in progress.\n')
